import{_ as o,W as p,s as d,u,ah as i,I as s,w as a,Z as l,A as e}from"./chunks/framework.ChbOY6p5.js";import"./chunks/theme.B6FFP-dx.js";const k=JSON.parse('{"title":"如何在 Linux 中实时监控日志文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中实时监控日志文件 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Linux 中实时监控日志文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中实时监控日志文件 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210822 How to Monitor Log Files in Real Time in Linux -Desktop and Server","title":"如何在 Linux 中实时监控日志文件","tag":"202108"},"relativePath":"202108/20210822 How to Monitor Log Files in Real Time in Linux -Desktop and Server.md","filePath":"[post].md"}'),r={name:"202108/20210822 How to Monitor Log Files in Real Time in Linux -Desktop and Server.md"};function g(m,t,b,v,h,c){const n=p("Link");return u(),d("div",null,[t[25]||(t[25]=i(`<h1 id="如何在-linux-中实时监控日志文件" tabindex="-1">如何在 Linux 中实时监控日志文件 <a class="header-anchor" href="#如何在-linux-中实时监控日志文件" aria-label="Permalink to 如何在 Linux 中实时监控日志文件">​</a></h1><blockquote><p>本教程解释了如何实时监控 Linux 日志文件（桌面、服务器或应用），以进行诊断和故障排除。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/30/082607bmf6nlud6sdy49rm.jpg" alt=""></p><p>当你在你的 Linux 桌面、服务器或任何应用中遇到问题时，你会首先查看各自的日志文件。日志文件通常是来自应用的文本和信息流，上面有一个时间戳。它可以帮助你缩小具体的实例，并帮助你找到任何问题的原因。它也可以帮助从网络上获得援助。</p><p>一般来说，所有的日志文件都位于 <code>/var/log</code> 中。这个目录包含以 <code>.log</code> 为扩展名的特定应用、服务的日志文件，它还包含单独的其他目录，这些目录包含其日志文件。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/log-files-in-var-log-1024x312.jpeg" alt="log files in var-log"></p><p>所以说，如果你想监控一堆日志文件或特定的日志文件。这里有一些你可以做到方法。</p><h3 id="实时监控-linux-日志文件" tabindex="-1">实时监控 Linux 日志文件 <a class="header-anchor" href="#实时监控-linux-日志文件" aria-label="Permalink to 实时监控 Linux 日志文件">​</a></h3><h4 id="使用-tail-命令" tabindex="-1">使用 tail 命令 <a class="header-anchor" href="#使用-tail-命令" aria-label="Permalink to 使用 tail 命令">​</a></h4><p>使用 <code>tail</code> 命令是实时跟踪日志文件的最基本方法。特别是，如果你所在的服务器只有一个终端，没有 GUI。这是很有帮助的。</p><p>比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tail /path/to/log/file</span></span></code></pre></div><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/Monitoring-multiple-log-files-via-tail-1024x444.jpeg" alt="Monitoring multiple log files via tail"></p><p>使用开关 <code>-f</code> 来跟踪日志文件，它是实时更新的。例如，如果你想跟踪 <code>syslog</code>，你可以使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tail -f /var/log/syslog</span></span></code></pre></div><p>你可以用一个命令监控多个日志文件，使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tail -f /var/log/syslog /var/log/dmesg</span></span></code></pre></div><p>如果你想监控 http 或 sftp 或任何服务器，你也可以在这个命令中监控它们各自的日志文件。</p><p>记住，上述命令需要管理员权限。</p><h4 id="使用-lnav-日志文件浏览器" tabindex="-1">使用 lnav（日志文件浏览器） <a class="header-anchor" href="#使用-lnav-日志文件浏览器" aria-label="Permalink to 使用 lnav（日志文件浏览器）">​</a></h4><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/lnav-Running-1024x447.jpeg" alt="lnav Running"></p><p><code>lnav</code> 是一个很好的工具，你可以用它来通过彩色编码的信息以更有条理的方式监控日志文件。在 Linux 系统中，它不是默认安装的。你可以用下面的命令来安装它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install lnav ### Ubuntu</span></span>
<span class="line"><span>sudo dnf install lnav ### Fedora</span></span></code></pre></div>`,23)),s("p",null,[t[1]||(t[1]=a("好的是，如果你不想安装它，你可以直接下载其预编译的可执行文件，然后在任何地方运行。甚至从 U 盘上也可以。它不需要设置，而且有很多功能。使用 ")),t[2]||(t[2]=s("code",null,"lnav",-1)),t[3]||(t[3]=a("，你可以通过 SQL 查询日志文件，以及其他很酷的功能，你可以在它的 ")),l(n,{href:"https://lnav.org/features"},{default:e(()=>t[0]||(t[0]=[a("官方网站")])),_:1}),t[4]||(t[4]=a(" 上了解。"))]),t[26]||(t[26]=i(`<p>一旦安装，你可以简单地用管理员权限从终端运行 <code>lnav</code>，它将默认显示 <code>/var/log</code> 中的所有日志并开始实时监控。</p><h4 id="关于-systemd-的-journalctl-说明" tabindex="-1">关于 systemd 的 journalctl 说明 <a class="header-anchor" href="#关于-systemd-的-journalctl-说明" aria-label="Permalink to 关于 systemd 的 journalctl 说明">​</a></h4><p>今天所有的现代 Linux 发行版大多使用 systemd。systemd 提供了运行 Linux 操作系统的基本框架和组件。systemd 通过 <code>journalctl</code> 提供日志服务，帮助管理所有 systemd 服务的日志。你还可以通过以下命令实时监控各个 systemd 服务和日志。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>journalctl -f</span></span></code></pre></div><p>下面是一些具体的 <code>journalctl</code> 命令，可以在一些情况下使用。你可以将这些命令与上面的 <code>-f</code> 开关结合起来，开始实时监控。</p><ul><li>对紧急系统信息，使用：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>journalctl -p 0</span></span></code></pre></div></li><li>显示带有解释的错误：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>journalctl -xb -p 3</span></span></code></pre></div></li><li>使用时间控制来过滤输出：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>journalctl --since &quot;2020-12-04 06:00:00&quot;</span></span>
<span class="line"><span>journalctl --since &quot;2020-12-03&quot; --until &quot;2020-12-05 03:00:00&quot;</span></span>
<span class="line"><span>journalctl --since yesterday</span></span>
<span class="line"><span>journalctl --since 09:00 --until &quot;1 hour ago&quot;</span></span></code></pre></div></li></ul>`,6)),s("p",null,[t[6]||(t[6]=a("如果你想了解更多关于 ")),t[7]||(t[7]=s("code",null,"journalctl",-1)),t[8]||(t[8]=a(" 的细节，我已经写了一个 ")),l(n,{href:"https://www.debugpoint.com/2020/12/systemd-journalctl/"},{default:e(()=>t[5]||(t[5]=[a("指南")])),_:1}),t[9]||(t[9]=a("。"))]),t[27]||(t[27]=s("h3",{id:"结束语",tabindex:"-1"},[a("结束语 "),s("a",{class:"header-anchor",href:"#结束语","aria-label":"Permalink to 结束语"},"​")],-1)),t[28]||(t[28]=s("p",null,"我希望这些命令和技巧能帮助你找出桌面或服务器问题/错误的根本原因。对于更多的细节，你可以随时参考手册，摆弄各种开关。如果你对这篇文章有什么意见或看法，请在下面的评论栏告诉我。",-1)),t[29]||(t[29]=s("p",null,"加油。",-1)),t[30]||(t[30]=s("hr",null,null,-1)),s("p",null,[t[11]||(t[11]=a("via: ")),l(n,{href:"https://www.debugpoint.com/2021/08/monitor-log-files-real-time/"},{default:e(()=>t[10]||(t[10]=[a("https://www.debugpoint.com/2021/08/monitor-log-files-real-time/")])),_:1})]),s("p",null,[t[16]||(t[16]=a("作者：")),l(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>t[12]||(t[12]=[a("Arindam")])),_:1}),t[17]||(t[17]=a(" 选题：")),l(n,{href:"https://github.com/lujun9972"},{default:e(()=>t[13]||(t[13]=[a("lujun9972")])),_:1}),t[18]||(t[18]=a(" 译者：")),l(n,{href:"https://github.com/geekpi"},{default:e(()=>t[14]||(t[14]=[a("geekpi")])),_:1}),t[19]||(t[19]=a(" 校对：")),l(n,{href:"https://github.com/wxy"},{default:e(()=>t[15]||(t[15]=[a("wxy")])),_:1})]),s("p",null,[t[22]||(t[22]=a("本文由 ")),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>t[20]||(t[20]=[a("LCTT")])),_:1}),t[23]||(t[23]=a(" 原创编译，")),l(n,{href:"https://linux.cn/"},{default:e(()=>t[21]||(t[21]=[a("Linux中国")])),_:1}),t[24]||(t[24]=a(" 荣誉推出"))])])}const y=o(r,[["render",g]]);export{k as __pageData,y as default};
